CREATE DATABASE IF NOT EXISTS moodcanvas_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE moodcanvas_db;
CREATE TABLE IF NOT EXISTS users (userID INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,passwordHash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',theme VARCHAR(50) NOT NULL DEFAULT 'warm',createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mood_entries (moodID INT AUTO_INCREMENT PRIMARY KEY,userID INT NOT NULL,moodText TEXT NOT NULL,moodTag VARCHAR(50),submittedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(userID) REFERENCES users(userID) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS journal_entries (journalID INT AUTO_INCREMENT PRIMARY KEY,userID INT NOT NULL,artworkID VARCHAR(100) NOT NULL,title VARCHAR(255),artist VARCHAR(255),imageURL TEXT,museum VARCHAR(100),savedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_user_artwork(userID,artworkID),FOREIGN KEY(userID) REFERENCES users(userID) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS user_artworks (artworkID CHAR(36) PRIMARY KEY,userID INT NOT NULL,title VARCHAR(180) NOT NULL,artist VARCHAR(180) NOT NULL,description VARCHAR(1000),moodTag VARCHAR(50) NOT NULL,contentType VARCHAR(30) NOT NULL,imageData MEDIUMBLOB NOT NULL,createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(userID) REFERENCES users(userID) ON DELETE CASCADE);
